const localNuc=['127.0.0.1','localhost','::1'].includes(location.hostname)&&!window.DartsAndroid;
const localOwner=localNuc||!!window.DartsAndroid?.isLocalMode?.();
const CENTRAL_SERVER='https://180-hitters-online.180-hitters-online.workers.dev';
const hostOpen=document.createElement('button');hostOpen.id='online-host-open';hostOpen.type='button';hostOpen.textContent='Dartbaan aanmaken';
const joinOpen=document.createElement('button');joinOpen.id='online-join-open';joinOpen.type='button';joinOpen.textContent='Deelnemen aan online dartbaan';document.getElementById('top-actions').append(hostOpen,joinOpen);
const dialog=document.createElement('dialog');dialog.id='online-dialog';dialog.className='online-dialog';dialog.innerHTML=`<h2 id="online-title">Online darten - 4 op een rij</h2><p id="online-intro"></p><fieldset id="online-host-section"><legend>Dartbaan aanmaken</legend><label>Jouw naam<input id="online-host-name" maxlength="24" autocomplete="name"></label><label>Totaal aantal spelers, inclusief jezelf<select id="online-capacity"><option>2</option><option>3</option><option>4</option></select></label><p>Je bent na het aanmaken automatisch speler 1. Deel de uitnodiging met de andere spelers en neem niet zelf nogmaals deel.</p><button id="online-host" class="primary wide">Dartbaan aanmaken</button></fieldset><fieldset id="online-join-section"><legend>Deelnemen aan online dartbaan</legend><label>Jouw naam<input id="online-guest-name" maxlength="24" autocomplete="name"></label><label>Uitnodigingslink<input id="online-invite-input" autocomplete="off" placeholder="https://...workers.dev/?dartbaan=ABC123"></label><button id="online-join" class="primary wide">Deelnemen aan dartbaan</button></fieldset><section id="online-active" hidden><h3>Actieve dartbaan</h3><p id="online-invite" class="online-invite" tabindex="0"></p><button id="online-copy" class="wide">Uitnodiging kopiëren</button><button id="online-reset" class="wide">Dartbaan leegmaken voor nieuw spel</button></section><p id="online-status" class="online-dialog-status" role="status"></p><div class="online-actions"><button id="online-leave">Dartbaan verlaten</button><button id="online-close">Sluiten</button></div>`;document.body.append(dialog);
const indicator=document.createElement('div');indicator.id='online-indicator';indicator.hidden=true;document.body.append(indicator);
const $=id=>document.getElementById(id);let session=null,remote=null,syncing=false,socket=null,reconnectTimer=null;
async function json(url,options={}){const response=await fetch(url,{cache:'no-store',...options});let data={};try{data=await response.json();}catch{}if(!response.ok){const error=Error(data.error||`Verbinding mislukt (${response.status}).`);error.status=response.status;error.data=data;throw error;}return data;}
async function localState(){return json('/api/state');}
async function saveLocal(match){const current=await localState();if(JSON.stringify(current.match?.state)===JSON.stringify(match?.state))return current;return json('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:current.revision,match})});}
async function saveSession(value){session=value;await json('/api/online/local',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(value)});paint();if(session.active&&localOwner)connect();}
function invite(){return session?.active?`${session.base}/?dartbaan=${session.code}`:'';}
function paint(state=null){
 const active=!!session?.active;$('online-active').hidden=!active;$('online-leave').hidden=!active;$('online-reset').hidden=!active||session.role!==0;$('online-invite').textContent=active?invite():'';indicator.hidden=!active;document.body.classList.toggle('online-session',active);
 if(!active){document.body.classList.remove('online-waiting');return;}
 const current=state||remote?.match,waiting=!session.ready||(current?.state?.active!==undefined&&current.state.active!==session.role);document.body.classList.toggle('online-waiting',waiting);
 const count=current?.state?.players?.filter(player=>!player.name.startsWith('Wachten op speler')).length;
 indicator.textContent=`Online dartbaan ${session.code} - speler ${session.role+1}${count?` - ${count}/${current.state.players.length} aanwezig`:''}${!session.ready?' - wacht op spelers':current?.state?.phase==='playing'?(waiting?' - tegenstander aan de beurt':' - jij bent aan de beurt'):''}`;
}
function parseInvite(value){const url=new URL(value.trim()),code=(url.searchParams.get('dartbaan')||url.hash.replace(/^#/,'')).toUpperCase();if(url.protocol!=='https:'||!/^[A-Z2-9]{6}$/.test(code))throw Error('Gebruik een geldige uitnodigingslink van 180 Hitters.');return {base:url.origin,code};}
async function updateRemote(value){
 if(value.closed){socket=null;remote=null;await saveSession({active:false,ready:false,role:null,code:'',base:'',key:'',remoteRevision:0});$('online-status').textContent=value.error||'De dartbaan is gesloten.';return;}
 remote=value;const ready=value.joined>=value.capacity;
 if(session.ready!==ready){session.ready=ready;await json('/api/online/local',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(session)});}
 const local=await localState(),localHistory=local.match?.state?.history?.length??-1,remoteHistory=value.match?.state?.history?.length??-1;
 if(localHistory===remoteHistory+1&&value.match.state.active===session.role)return push();
 if(value.revision!==session.remoteRevision||JSON.stringify(local.match?.state)!==JSON.stringify(value.match?.state)){await saveLocal(value.match);session.remoteRevision=value.revision;await json('/api/online/local',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(session)});}
 paint(value.match);
}
async function push(){if(syncing||!session?.active||!localOwner)return;syncing=true;try{
 if(!remote)remote=await json(`${session.base}/rooms/${session.code}?key=${encodeURIComponent(session.key)}`);
 const local=await localState(),lh=local.match?.state?.history?.length??-1,rh=remote.match?.state?.history?.length??-1;
 if(lh===rh+1&&remote.match.state.active===session.role){remote=await json(`${session.base}/rooms/${session.code}/state`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:session.key,revision:remote.revision,match:local.match})});session.remoteRevision=remote.revision;await json('/api/online/local',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(session)});paint(remote.match);}
 }catch(error){$('online-status').textContent=error.message;}finally{syncing=false;}}
function connect(){if(!localOwner||!session?.active||socket?.readyState===WebSocket.OPEN||socket?.readyState===WebSocket.CONNECTING)return;clearTimeout(reconnectTimer);const url=`${session.base.replace(/^http/,'ws')}/rooms/${session.code}/socket?key=${encodeURIComponent(session.key)}`;socket=new WebSocket(url);socket.onmessage=event=>{try{void updateRemote(JSON.parse(event.data));}catch{}};socket.onopen=()=>{$('online-status').textContent='Realtime verbonden.';};socket.onclose=()=>{socket=null;if(session?.active)reconnectTimer=setTimeout(connect,1500);};socket.onerror=()=>socket?.close();}
async function openOnline(mode){try{session=await json('/api/online/local');paint();if(session.active&&localOwner)connect();}catch{}const host=mode==='host';$('online-title').textContent=host?'Dartbaan aanmaken - 4 op een rij':'Deelnemen aan online dartbaan';$('online-intro').textContent=host?'Maak een besloten dartbaan voor twee tot vier spelers. Het gekozen aantal is inclusief jezelf.':'Open de uitnodiging die je van de maker van de dartbaan hebt ontvangen.';$('online-host-section').hidden=!host;$('online-join-section').hidden=host;$('online-status').textContent='';dialog.showModal();}
hostOpen.onclick=()=>void openOnline('host');joinOpen.onclick=()=>void openOnline('join');$('online-close').onclick=()=>dialog.close();
$('online-host').onclick=async()=>{const name=$('online-host-name').value.trim(),capacity=Number($('online-capacity').value);if(!name)return $('online-status').textContent='Vul jouw naam in.';if(!CENTRAL_SERVER)return $('online-status').textContent='De gratis online server is nog niet gekoppeld.';$('online-host').disabled=true;try{
 const {newMatch}=await import('./engine.js'),names=[name,...Array.from({length:capacity-1},(_,index)=>`Wachten op speler ${index+2}`)],state=newMatch(names,0,'single',1,{game:'fourinarow'}),match={state,undo:[]};await saveLocal(match);
 remote=await json(CENTRAL_SERVER+'/rooms',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,match})});await saveLocal(remote.match);await saveSession({active:true,ready:remote.joined>=remote.capacity,role:remote.role,code:remote.code,base:CENTRAL_SERVER,key:remote.key,remoteRevision:remote.revision});$('online-status').textContent='Dartbaan gereed. Deel de uitnodiging.';
 }catch(error){$('online-status').textContent=error.message;}finally{$('online-host').disabled=false;}};
$('online-join').onclick=async()=>{const name=$('online-guest-name').value.trim();if(!name)return $('online-status').textContent='Vul jouw naam in.';$('online-join').disabled=true;try{const target=parseInvite($('online-invite-input').value);remote=await json(`${target.base}/rooms/${target.code}/join`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});await saveLocal(remote.match);await saveSession({active:true,ready:remote.joined>=remote.capacity,role:remote.role,code:remote.code,base:target.base,key:remote.key,remoteRevision:remote.revision});$('online-status').textContent='Verbonden met de dartbaan.';}catch(error){$('online-status').textContent=error.message;}finally{$('online-join').disabled=false;}};
$('online-copy').onclick=async()=>{try{await navigator.clipboard.writeText(invite());$('online-status').textContent='Uitnodiging gekopieerd.';}catch{$('online-invite').focus();const selection=getSelection();selection.removeAllRanges();const range=document.createRange();range.selectNodeContents($('online-invite'));selection.addRange(range);$('online-status').textContent='Selecteer en kopieer de uitnodiging.';}};
$('online-reset').onclick=async()=>{if(session?.role!==0||!remote)return;const old={...session},capacity=remote.capacity,name=remote.match?.state?.players?.[0]?.name||'Speler 1';$('online-reset').disabled=true;try{const {newMatch}=await import('./engine.js'),names=[name,...Array.from({length:capacity-1},(_,index)=>`Wachten op speler ${index+2}`)],state=newMatch(names,0,'single',1,{game:'fourinarow'}),match={state,undo:[]},next=await json(CENTRAL_SERVER+'/rooms',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,match})});socket?.close();socket=null;await json(`${old.base}/rooms/${old.code}/close`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:old.key})});remote=next;await saveLocal(next.match);await saveSession({active:true,ready:false,role:0,code:next.code,base:CENTRAL_SERVER,key:next.key,remoteRevision:next.revision});$('online-status').textContent='Nieuwe lege dartbaan gereed. Deel de nieuwe uitnodiging.';}catch(error){$('online-status').textContent=error.message;}finally{$('online-reset').disabled=false;}};
$('online-leave').onclick=async()=>{try{socket?.close();socket=null;remote=null;await saveSession({active:false,ready:false,role:null,code:'',base:'',key:'',remoteRevision:0});$('online-status').textContent='Dartbaan verlaten.';}catch(error){$('online-status').textContent=error.message;}};
for(const event of ['match-persisted','match-synchronized'])document.addEventListener(event,()=>void push());
document.addEventListener('click',event=>{if(!session?.active)return;const blocked=document.body.classList.contains('online-waiting')&&event.target.closest('.four-board,.four-controls')||event.target.closest('#undo,#redo,#edit-match,#team-manager,#settings');if(blocked){event.preventDefault();event.stopImmediatePropagation();$('online-status').textContent='Verlaat eerst de online dartbaan om deze functie te gebruiken.';}},true);
async function restore(){try{session=await json('/api/online/local');paint();if(session.active&&localOwner){remote=await json(`${session.base}/rooms/${session.code}?key=${encodeURIComponent(session.key)}`);await updateRemote(remote);connect();}}catch(error){if(session?.active){indicator.hidden=false;indicator.textContent='Online dartbaan - verbinding herstellen...';$('online-status').textContent=error.message;setTimeout(restore,2500);}}}restore();
